import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import { generatePrePaintScript } from './shared/prePaintScript.js';

// Pre-paint boot injection (PLAN.MD §13): the inline <head> script that
// applies the user's prefs BEFORE any module loads is GENERATED by
// shared/prePaintScript.js from registry data — index.html carries only a
// marker comment, so the script cannot drift from the module appliers or
// the registry. transformIndexHtml covers both `vite dev` and `vite build`.
function prePaintInject() {
  return {
    name: 'pre-paint-inject',
    transformIndexHtml(html) {
      const MARKER = '<!-- pre-paint:generated -->';
      if (!html.includes(MARKER)) return html; // marker removed → no injection
      return html.replace(MARKER, `<script>${generatePrePaintScript()}</script>`);
    },
  };
}

// Dev-proxy hardening for the one-shot 503 class. When the backend (:3000) is
// restarted, pooled keep-alive sockets die; the next request through such a
// socket fails with ECONNRESET or stalls until the socket gives up — users
// saw a single /api/health 503 with no matching server log entry (the proxy
// answered while the backend was down/restarting). For idempotent methods
// (GET/HEAD) this plugin fetches the upstream directly and, on connection
// failure, retries ONCE after a short delay so a typical dev restart
// (~1–2s of dead window) is bridged transparently; a retried POST could
// double-apply, so writes keep using the stock proxy unchanged. If the
// delayed retry also fails, the backend is genuinely unreachable and the
// client gets an explicit 503 with Retry-After.
const BACKEND = 'http://localhost:3000'; // rider: also used by backendRetryProxy
const IDEMPOTENT = new Set(['GET', 'HEAD']);
const RETRY_DELAY_MS = 1_000; // bridges a typical dev-server restart window
const UPSTREAM_TIMEOUT_MS = 4_000; // fail fast so the retry lands in-window
const RETRY_BUDGET_MS = 6_000; // overall client-visible deadline

// Headers that describe the hop or the body encoding undici rewrites.
const HOP_BY_HOP = new Set(['connection', 'keep-alive', 'transfer-encoding', 'upgrade', 'proxy-authenticate', 'proxy-authorization', 'te', 'trailer']);

// One upstream attempt. The timeout covers ONLY the pre-response phase
// (connect + response headers): a manual AbortController is cleared the
// moment headers arrive, so large response BODIES stream without a deadline.
// The previous unconditional AbortSignal.timeout(4s) kept ticking during
// body streaming and killed long transfers mid-flight (attachment video
// seek, conversation ZIP exports) — a 4s ceiling on any GET body through
// the dev proxy. Rejects on pre-response timeout/connection failure
// (retryable); resolves with the Response otherwise.
async function attemptFetch(req) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), UPSTREAM_TIMEOUT_MS);
  try {
    return await fetch(`${BACKEND}${req.url}`, {
      method: req.method,
      headers: { host: 'localhost:3000', ...req.headers }, // changeOrigin equivalent
      signal: controller.signal,
    });
  } finally {
    clearTimeout(timer); // headers arrived (or failed) — body may still stream
  }
}

async function proxyWithRetry(req, res) {
  const idempotent = IDEMPOTENT.has(req.method);
  const deadline = Date.now() + RETRY_BUDGET_MS;
  let upstream;
  try {
    upstream = await attemptFetch(req);
  } catch {
    if (idempotent) {
      // One delayed retry: wait out the dead window, then try a fresh
      // connection — unless the client would time out first.
      const wait = Math.min(RETRY_DELAY_MS, Math.max(0, deadline - Date.now()));
      if (wait > 0) await new Promise(r => setTimeout(r, wait));
      if (Date.now() < deadline) {
        try { upstream = await attemptFetch(req); } catch { /* falls through to 503 */ }
      }
    }
    if (!upstream) {
      if (!res.writableEnded) {
        res.writeHead(503, { 'content-type': 'application/json', 'retry-after': '1' });
        res.end(JSON.stringify({ error: 'backend unreachable (dev proxy retry exhausted)' }));
      }
      return;
    }
  }
  const headers = {};
  upstream.headers.forEach((v, k) => {
    if (!HOP_BY_HOP.has(k) && k !== 'content-length' && k !== 'content-encoding') headers[k] = v;
  });
  res.writeHead(upstream.status, headers);
  if (upstream.body) {
    // Stream the body without a deadline. An error here (client gone,
    // upstream reset mid-transfer) must be handled on the SOURCE — pipe
    // does not forward it, and an unhandled 'error' event would crash
    // the Vite dev server.
    Readable.fromWeb(upstream.body).on('error', () => {
      if (!res.writableEnded) res.destroy();
    }).pipe(res);
  }
  else res.end();
}

// Runs before Vite's internal middlewares (including its proxy), so idempotent
// /api and /uploads traffic takes the retrying path and everything else —
// POST/PUT/PATCH/DELETE and the /ws WebSocket — falls through to the stock proxy.
function backendRetryProxy() {
  return {
    name: 'dev-proxy-stale-socket-retry',
    configureServer(server) {
      server.middlewares.use((req, res, next) => {
        if ((req.url.startsWith('/api') || req.url.startsWith('/uploads')) && IDEMPOTENT.has(req.method)) {
          proxyWithRetry(req, res);
          return;
        }
        next();
      });
    },
  };
}

export default defineConfig({
  plugins: [react(), prePaintInject()],
  server: {
    host: '0.0.0.0',
    port: 5174,
    proxy: {
      '/api': {
        target: BACKEND,
        changeOrigin: true,
      },
      '/ws': {
        target: 'ws://localhost:3000',
        ws: true,
      },
      '/uploads': {
        target: BACKEND,
        changeOrigin: true,
      },
    },
    watch: {
      // Explicitly naming the database files so Vite stops hard-reloading the UI
      ignored: [
        '**/database.sqlite',
        '**/database.sqlite-journal',
        '**/database.sqlite-wal',
        '**/database.sqlite-shm',
        '**/uploads/**'
      ]
    }
  }
});
